31		cmd.AddCommand(c.NewOrgCommand())
32	
33		cmd.PersistentPreRunE = func(cmd *cobra.Command, args []string) error {
34			// Skip check for completion and help commands
35			fullPath := cmd.CommandPath()
36			if strings.Contains(fullPath, " completion") || strings.Contains(fullPath, " help") || cmd.Name() == "help" {
37				return nil
38			}
39	
40			missing := []string{}
41			for _, envVar := range []string{"ENV", "PORTAL_API_KEY", "PORTAL_API_TOKEN"} {
42				if os.Getenv(envVar) == "" {
43					missing = append(missing, envVar)
44				}
45			}
46	
47			if len(missing) > 0 {
48				fmt.Printf("Warning: The following required environment variables are not set: %s\n\n", strings.Join(missing, ", "))
49				cmd.Usage()
50				os.Exit(1)
51			}
52	
53			internalClient, err := portal.NewClient(portal.GetClientConfig())
54			if err != nil {
55				return err
56			}
57			c.client = internalClient
58			return nil
59		}
60	
61		return cmd
62	}
63	
64	func Execute() {
65		if err := RootCommand().Execute(); err != nil {
66			os.Exit(1)
67		}
68	}
